window.blogDetail = {"blogId":1532916159,"blogType":0,"pubTime":"2018-07-30 10:02","cate":"个人日记","cateHex":"b8f6c8cbc8d5bcc7","title":"“达则兼济天下，穷则独善其身”—“诗魔”白居易","commentNum":0,"effect1":4195328,"effect2":524294,"ar":0,"block":0,"inproc":true,"appeal":0,"abstract":"“缀玉联珠六十年 ，谁叫冥路作诗仙。浮云不系名居易，造化无为字乐天。童子解吟长恨曲，胡儿能唱琵琶篇。文章已满行人耳，一度思卿一怆然。”这是唐宣宗李忱在白居易去世后，亲自为他题写的一首吊唁诗。白居易，唐代继杜甫之后又一位现实主义大诗人， 这是后世人对白居易的总体评价。纵观白居易的一生，他少年得志， 28岁考中进士，34岁，被授予翰林学士，在朝任职。35岁任左拾遗，至44岁时，因直言上书请求捉拿刺杀宰...","artype":-1,"arUins":"","blogid":1532916159,"voteids":0,"pubtime":1532916159,"replynum":0,"category":"个人日记","effect":4195328,"exblogtype":0,"sus_flag":false,"friendrelation":[],"lp_type":0,"lp_id":0,"lp_style":0,"lp_flag":0,"orguin":619774944,"orgblogid":1532916159,"mention_uins":[],"attach":[],"comments":[],"html":"","custom_title":"“达则兼济天下，穷则独善其身”—“诗魔”白居易","custom_html":"","uniKey":"http://user.qzone.qq.com/619774944/blog/1532916159"}